'use strict';

// MODULES //

var dcabs1 = require( '@stdlib/blas/base/dcabs1' );


// MAIN //

/**
* Computes the sum of the absolute values of each element in a double-precision complex floating-point vector.
*
* @param {PositiveInteger} N - number of indexed elements
* @param {Complex64Array} x - input array
* @param {integer} stride - `x` stride length
* @param {NonNegativeInteger} offset - starting index for `x`
* @returns {number} sum
*
* @example
* var Complex128Array = require( '@stdlib/array/complex128' );
*
* var x = new Complex128Array( [ -2.0, 1.0, 3.0, -5.0, 4.0, 0.0, -1.0, -3.0 ] );
*
* var sum = dzasum( x.length, x, 1, 0 );
* // returns 19.0
*/
function dzasum( N, x, stride, offset ) {
	var sum;
	var ix;
	var i;

	sum = 0.0;
	if ( N <= 0 ) {
		return sum;
	}
	ix = offset;
	for ( i = 0; i < N; i++ ) {
		sum += dcabs1( x.get( ix ) );
		ix += stride;
	}
	return sum;
}


// EXPORTS //

module.exports = dzasum;
